-- Own overrides only; effective appearance is resolved when reading.
CREATE TABLE planner_icons (
 id TEXT PRIMARY KEY NOT NULL,
 name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 120),
 category TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('builtin','custom')),
 mime TEXT NOT NULL CHECK(mime IN ('image/png','image/svg+xml')),
 image BLOB,
 checksum TEXT NOT NULL,
 width INTEGER NOT NULL CHECK(width BETWEEN 1 AND 1024),
 height INTEGER NOT NULL CHECK(height BETWEEN 1 AND 1024),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 deleted_at TEXT,
 CHECK((kind='builtin' AND image IS NULL AND mime='image/svg+xml') OR (kind='custom' AND image IS NOT NULL AND mime='image/png' AND length(image)<=1048576))
);
CREATE TABLE icon_events (
 id TEXT PRIMARY KEY NOT NULL,
 icon_id TEXT NOT NULL REFERENCES planner_icons(id),
 action TEXT NOT NULL,
 operation_id TEXT NOT NULL,
 changes_json TEXT NOT NULL CHECK(json_valid(changes_json)),
 created_at TEXT NOT NULL
);
CREATE INDEX icon_events_object ON icon_events(icon_id,created_at);
CREATE TRIGGER icon_events_immutable_update BEFORE UPDATE ON icon_events BEGIN SELECT RAISE(ABORT,'immutable icon history'); END;
ALTER TABLE projects ADD COLUMN color_id TEXT CHECK(color_id IS NULL OR color_id IN ('slate','blue','cyan','teal','green','lime','yellow','orange','coral','rose','purple','indigo'));
ALTER TABLE projects ADD COLUMN icon_id TEXT REFERENCES planner_icons(id);
CREATE INDEX projects_icon ON projects(icon_id);
ALTER TABLE tasks ADD COLUMN color_id TEXT CHECK(color_id IS NULL OR color_id IN ('slate','blue','cyan','teal','green','lime','yellow','orange','coral','rose','purple','indigo'));
ALTER TABLE tasks ADD COLUMN icon_id TEXT REFERENCES planner_icons(id);
CREATE INDEX tasks_icon ON tasks(icon_id);
